def correct_bracketing(brackets: str) -> bool:
    opening_brackets = 0
    closing_brackets = 0

    for bracket in brackets:
        if bracket == "<":
            opening_brackets += 1
        elif bracket == ">":
            closing_brackets += 1

    if opening_brackets != closing_brackets:
        return False

    stack = []
    for bracket in brackets:
        if bracket == "<":
            stack.append(bracket)
        elif bracket == ">":
            if not stack:
                return False
            stack.pop()

    return len(stack) == 0

