    # Calculate the sum of all integers in the list
    total_sum = sum(numbers)

    # Calculate the product of all integers in the list
    total_product = 1
    for num in numbers:
        total_product *= num

    # Return a tuple consisting of the sum and product
    return (total_sum, total_product)
